initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  // 計算結果を格納する配列
  let calculationResults = [];

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 成功メッセージ表示関数
  function showSuccess(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.style.borderLeftColor = '#44ff44';
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
      errorDiv.style.borderLeftColor = '#ff4444';
    }, 3000);
  }

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORES_TABLE);
    if (stores) {
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      stores.filter(s => s.有効フラグ).forEach(store => {
        const option = document.createElement('option');
        option.value = store.id;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      });
    }
  }

  // 需要予測データ表示
  function displayForecastData(forecasts) {
    const display = container.querySelector('#forecast-display');
    if (!forecasts || forecasts.length === 0) {
      display.innerHTML = '<p class="muted">該当する需要予測データがありません。</p>';
      return;
    }

    const totalForecast = forecasts.reduce((sum, f) => sum + (f.予測数量 || 0), 0);
    const avgAccuracy = forecasts.reduce((sum, f) => sum + (f.予測精度 || 0), 0) / forecasts.length;

    display.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 1rem;">
        <div>
          <div style="font-size: 0.875rem; color: var(--text-muted);">総予測需要量</div>
          <div style="font-size: 1.25rem; font-weight: bold; color: var(--text);">${totalForecast.toLocaleString()}個</div>
        </div>
        <div>
          <div style="font-size: 0.875rem; color: var(--text-muted);">平均予測精度</div>
          <div style="font-size: 1.25rem; font-weight: bold; color: var(--text);">${avgAccuracy.toFixed(1)}%</div>
        </div>
        <div>
          <div style="font-size: 0.875rem; color: var(--text-muted);">対象商品数</div>
          <div style="font-size: 1.25rem; font-weight: bold; color: var(--text);">${forecasts.length}商品</div>
        </div>
      </div>
    `;
  }

  // 在庫データ表示
  function displayCurrentStock(products) {
    const display = container.querySelector('#current-stock-display');
    if (!products || products.length === 0) {
      display.innerHTML = '<p class="muted">該当する商品がありません。</p>';
      return;
    }

    // 仮の在庫数を生成（実際のシステムでは在庫テーブルから取得）
    const stockData = products.map(p => ({
      商品名: p.商品名,
      商品コード: p.商品コード,
      現在在庫: Math.floor(Math.random() * 500) + 50
    }));

    const totalStock = stockData.reduce((sum, s) => sum + s.現在在庫, 0);

    display.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 1rem; margin-bottom: 1rem;">
        <div>
          <div style="font-size: 0.875rem; color: var(--text-muted);">総在庫数</div>
          <div style="font-size: 1.25rem; font-weight: bold; color: var(--text);">${totalStock.toLocaleString()}個</div>
        </div>
        <div>
          <div style="font-size: 0.875rem; color: var(--text-muted);">在庫商品数</div>
          <div style="font-size: 1.25rem; font-weight: bold; color: var(--text);">${stockData.length}商品</div>
        </div>
      </div>
      <div style="max-height: 200px; overflow-y: auto;">
        <table style="width: 100%; font-size: 0.875rem;">
          <thead>
            <tr style="background: var(--bg-card);">
              <th style="padding: 0.5rem; text-align: left; color: var(--text);">商品コード</th>
              <th style="padding: 0.5rem; text-align: left; color: var(--text);">商品名</th>
              <th style="padding: 0.5rem; text-align: right; color: var(--text);">在庫数</th>
            </tr>
          </thead>
          <tbody>
            ${stockData.map(s => `
              <tr>
                <td style="padding: 0.5rem; color: var(--text);">${s.商品コード}</td>
                <td style="padding: 0.5rem; color: var(--text);">${s.商品名}</td>
                <td style="padding: 0.5rem; text-align: right; color: var(--text);">${s.現在在庫.toLocaleString()}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  // 計算結果テーブル再描画
  function renderResults(results) {
    const tbody = container.querySelector('#results-tbody');
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="muted" style="text-align: center; padding: 2rem;">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id || r.商品コード}">
        <td><a href="#" class="product-detail-link" data-id="${r.商品ID}" style="color: var(--primary); text-decoration: none;">${r.商品名}</a></td>
        <td>${r.商品コード}</td>
        <td style="text-align: right;">${(r.予測需要量 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(r.現在在庫 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(r.安全在庫 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(r.発注点 || 0).toLocaleString()}</td>
        <td style="text-align: right; font-weight: bold;">${(r.推奨発注量 || 0).toLocaleString()}</td>
        <td style="text-align: right;">¥${((r.推奨発注量 || 0) * (r.単価 || 0)).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary create-order-btn" data-id="${r.商品ID}">発注作成</button>
        </td>
      </tr>
    `).join('');
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 0;
    const reorderPoint = parseInt(container.querySelector('#reorder-point').value) || 0;

    if (!storeId) {
      showError('店舗を選択してください。');
      return false;
    }
    if (!category) {
      showError('商品カテゴリを選択してください。');
      return false;
    }
    if (!periodStart || !periodEnd) {
      showError('計算対象期間を設定してください。');
      return false;
    }
    if (new Date(periodStart) >= new Date(periodEnd)) {
      showError('期間の開始日は終了日より前に設定してください。');
      return false;
    }
    if (safetyStock < 0) {
      showError('安全在庫数は0以上の値を入力してください。');
      return false;
    }
    if (leadTime <= 0) {
      showError('リードタイムは1以上の値を入力してください。');
      return false;
    }
    if (reorderPoint < 0) {
      showError('発注点は0以上の値を入力してください。');
      return false;
    }

    return true;
  }

  // 発注量計算実行
  async function executeCalculation() {
    if (!validateInputs()) return;

    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 7;
    const reorderPoint = parseInt(container.querySelector('#reorder-point').value) || 0;

    try {
      // 商品データ取得
      const products = await window.aivicApi.list(PRODUCTS_TABLE);
      if (!products) {
        showError('商品データの取得に失敗しました。');
        return;
      }

      // カテゴリでフィルタリング
      const categoryProducts = products.filter(p => 
        p.有効フラグ && 
        p.AI予測対象フラグ && 
        (category === '食品' ? p.商品名.includes('食') : 
         category === '日用品' ? p.商品名.includes('日用') || p.商品名.includes('洗剤') : 
         category === '衣料品' ? p.商品名.includes('衣') || p.商品名.includes('服') : true)
      );

      if (categoryProducts.length === 0) {
        showError('選択したカテゴリに該当する商品がありません。');
        return;
      }

      // 需要予測データ取得
      const forecasts = await window.aivicApi.list(FORECAST_TABLE);
      if (!forecasts) {
        showError('需要予測データの取得に失敗しました。');
        return;
      }

      // 店舗・期間・商品でフィルタリング
      const relevantForecasts = forecasts.filter(f => 
        f.店舗ID === storeId &&
        new Date(f.予測対象日) >= new Date(periodStart) &&
        new Date(f.予測対象日) <= new Date(periodEnd) &&
        categoryProducts.some(p => p.id === f.商品ID)
      );

      if (relevantForecasts.length === 0) {
        showError('該当する需要予測データがありません。');
        return;
      }

      // 需要予測結果表示
      displayForecastData(relevantForecasts);

      // 在庫データ表示
      displayCurrentStock(categoryProducts);

      // 商品別に予測需要を集計して発注量計算
      const productForecasts = {};
      relevantForecasts.forEach(f => {
        if (!productForecasts[f.商品ID]) {
          productForecasts[f.商品ID] = {
            商品ID: f.商品ID,
            予測需要量: 0,
            予測精度: 0,
            count: 0
          };
        }
        productForecasts[f.商品ID].予測需要量 += f.予測数量 || 0;
        productForecasts[f.商品ID].予測精度 += f.予測精度 || 0;
        productForecasts[f.商品ID].count++;
      });

      // 計算結果生成
      calculationResults = Object.values(productForecasts).map(pf => {
        const product = categoryProducts.find(p => p.id === pf.商品ID);
        if (!product) return null;

        const avgAccuracy = pf.count > 0 ? pf.予測精度 / pf.count : 0;
        const currentStock = Math.floor(Math.random() * 500) + 50; // 仮の在庫数
        const dailyDemand = pf.予測需要量 / Math.max(1, (new Date(periodEnd) - new Date(periodStart)) / (1000 * 60 * 60 * 24));
        const leadTimeDemand = dailyDemand * leadTime;
        const calculatedReorderPoint = Math.max(reorderPoint, leadTimeDemand + safetyStock);

        // 発注量計算: 現在在庫が発注点を下回る場合に発注
        let recommendedOrder = 0;
        if (currentStock <= calculatedReorderPoint) {
          // 経済発注量の簡易計算（需要量の1.5倍を上限とする）
          const maxOrder = Math.ceil(pf.予測需要量 * 1.5);
          const minOrder = Math.max(product.最小発注数量 || 1, leadTimeDemand + safetyStock - currentStock);
          recommendedOrder = Math.min(maxOrder, Math.ceil(minOrder / (product.発注単位 || 1)) * (product.発注単位 || 1));
        }

        return {
          商品ID: product.id,
          商品名: product.商品名,
          商品コード: product.商品コード,
          予測需要量: Math.round(pf.予測需要量),
          現在在庫: currentStock,
          安全在庫: safetyStock,
          発注点: Math.round(calculatedReorderPoint),
          推奨発注量: recommendedOrder,
          単価: product.単価 || 0,
          予測精度: Math.round(avgAccuracy)
        };
      }).filter(r => r !== null);

      renderResults(calculationResults);
      showSuccess(`${calculationResults.length}商品の発注量計算が完了しました。`);

    } catch (error) {
      console.error('計算エラー:', error);
      showError('発注量計算中にエラーが発生しました。');
    }
  }

  // 条件クリア
  function clearConditions() {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#period-start').value = '';
    container.querySelector('#period-end').value = '';
    container.querySelector('#safety-stock').value = '';
    container.querySelector('#lead-time').value = '';
    container.querySelector('#reorder-point').value = '';

    // 表示エリアもクリア
    container.querySelector('#forecast-display').innerHTML = '<p class="muted">計算条件を設定して「計算実行」ボタンをクリックしてください。</p>';
    container.querySelector('#current-stock-display').innerHTML = '<p class="muted">店舗と商品カテゴリを選択すると在庫情報が表示されます。</p>';

    calculationResults = [];
    renderResults([]);
  }

  // 発注作成
  async function createOrder(productId) {
    const result = calculationResults.find(r => r.商品ID === productId);
    if (!result || result.推奨発注量 <= 0) {
      showError('発注量が0のため発注を作成できません。');
      return;
    }

    const storeId = container.querySelector('#store-select').value;
    const orderData = {
      店舗ID: storeId,
      商品ID: productId,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + (parseInt(container.querySelector('#lead-time').value) || 7) * 24 * 60 * 60 * 1000).toISOString(),
      発注数量: result.推奨発注量,
      予測数量: result.予測需要量,
      発注単価: result.単価,
      発注金額: result.推奨発注量 * result.単価,
      発注方法: 'AI推奨採用',
      発注ステータス: '発注済',
      仕入先ID: 'default-supplier',
      発注理由: 'AI需要予測に基づく自動発注',
      自動発注フラグ: false,
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    const saved = await window.aivicApi.save(ORDER_TABLE, orderData);
    if (saved) {
      showSuccess(`${result.商品名}の発注を作成しました。`);
    } else {
      showError('発注の作成に失敗しました。');
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-calculate').addEventListener('click', executeCalculation);
  container.querySelector('#btn-clear').addEventListener('click', clearConditions);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 商品詳細リンク
    const detailLink = e.target.closest('.product-detail-link');
    if (detailLink) {
      e.preventDefault();
      // 商品詳細画面への遷移（実装されている場合）
      showSuccess('商品詳細画面への遷移機能は今後実装予定です。');
      return;
    }

    // 発注作成ボタン
    const orderBtn = e.target.closest('.create-order-btn');
    if (orderBtn) {
      await createOrder(orderBtn.dataset.id);
      return;
    }
  });

  // 初期化
  loadStores();

  // デフォルト値設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  container.querySelector('#period-start').value = today.toISOString().split('T')[0];
  container.querySelector('#period-end').value = nextWeek.toISOString().split('T')[0];
  container.querySelector('#lead-time').value = '7';
}
